import { mkdtemp, readFile, rm, stat } from 'node:fs/promises';
import { join } from 'node:path';
// Capture destinations are generated by the broker, never supplied by clients.
export async function captureLibvirtConsole({ run, uuid, directory, maxBytes = 16 * 1024 * 1024 }) {
  const temporary = await mkdtemp(join(directory, 'capture-'));
  try {
    const file = join(temporary, 'console.png');
    await run(['screenshot', uuid, file, '--screen', '0']);
    if ((await stat(file)).size > maxBytes) throw Error('Invalid or oversized console PNG');
    const data = await readFile(file);
    if (
      data.length > maxBytes ||
      data.length < 24 ||
      !data.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) ||
      data.toString('ascii', 12, 16) !== 'IHDR'
    )
      throw Error('Invalid or oversized console PNG');
    const width = data.readUInt32BE(16),
      height = data.readUInt32BE(20);
    if (width < 1 || height < 1 || width > 8192 || height > 8192 || width * height > 33554432)
      throw Error('Console dimensions exceed capture bounds');
    return { image: data.toString('base64'), mimeType: 'image/png', width, height };
  } finally {
    await rm(temporary, { recursive: true, force: true });
  }
}
